"""Generates ESPHome YAML package configurations for HTTP OTA."""

from __future__ import annotations

import re
from typing import Any

from .const import DEFAULT_PUBLISH_DIR

_PROJECT_NAME_MAX = 32

NODE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,62}$")


def project_name(node: str) -> str:
    """Return 'local.<node>' capped at ESPHome's 32-character project.name limit."""
    name = f"local.{node}"
    return name if len(name) <= _PROJECT_NAME_MAX else name[:_PROJECT_NAME_MAX]


HEADER = """\
# ---------------------------------------------------------------------------
# Generated by ESPHome OTA. Managed automatically.
# ---------------------------------------------------------------------------
"""


def generate_inline_ota_package(
    base_url: str,
    slug: str,
    version: str | None = None,
    publish_dir: str = DEFAULT_PUBLISH_DIR,
    node: str = "",
    use_project: bool = True,
) -> dict[str, Any]:
    """Generate inline package dictionary for packages.esphome_ota."""
    pkg: dict[str, Any] = {
        "substitutions": {
            "ota_base_url": base_url.rstrip("/"),
            "ota_slug": slug,
        },
        "http_request": {
            "timeout": "60s",
        },
        "ota": [
            {"platform": "http_request"}
        ],
        "safe_mode": None,
        "update": [
            {
                "platform": "http_request",
                "id": "ota_update",
                "name": "Firmware",
                "source": f"${{ota_base_url}}/local/{publish_dir}/${{ota_slug}}.json",
                "update_interval": "6h",
            }
        ],
    }

    if use_project and node and version:
        pkg["esphome"] = {
            "project": {
                "name": project_name(node),
                "version": version,
            }
        }

    return pkg


def generate_inline_ota_yaml(
    base_url: str,
    slug: str,
    version: str | None = None,
    publish_dir: str = DEFAULT_PUBLISH_DIR,
    node: str = "",
    use_project: bool = True,
) -> str:
    """Generate YAML snippet for packages.esphome_ota."""
    clean_base_url = base_url.rstrip("/")
    proj_block = ""
    if use_project and node and version:
        proj_block = f"""    esphome:
      project:
        name: "{project_name(node)}"
        version: "{version}"\n"""

    return f"""\
  esphome_ota:
    substitutions:
      ota_base_url: "{clean_base_url}"
      ota_slug: "{slug}"
{proj_block}    http_request:
      timeout: 60s

    ota:
      - platform: http_request

    safe_mode:

    update:
      - platform: http_request
        id: ota_update
        name: "Firmware"
        source: "${{ota_base_url}}/local/{publish_dir}/${{ota_slug}}.json"
        update_interval: 6h
"""


def generate_device_wrapper_yaml(
    node: str,
    token: str = "",
    version: str = "1.0.0",
    package_file: str = "update.yaml",
    package_dir: str = "ota_server",
) -> str:
    """Generate legacy device wrapper YAML."""
    slug = f"{node}_{token}" if token else node
    p_name = project_name(node)
    return f"""\
{HEADER}
substitutions:
  ota_device: {node}
  ota_slug: {slug}

esphome:
  project:
    name: "{p_name}"
    version: "{version}"

packages:
  ota_base: !include ../{package_file}
"""
